Emotes = {}

function LoadEmotes()
	debugLog("LoadEmotes starting")
	local success, result = pcall(function()
		local response = loadModule("data/emotes")
		return HttpService:JSONDecode(response)
	end)
	debugLog("LoadEmotes JSON loaded. success=" .. tostring(success) .. " resultType=" .. type(result))
	
	if success and result then
		local data = type(result) == "table" and (result.data or result)
		local _seenIds = {}
		for _, emote in ipairs(data) do
			if emote.id and emote.name then
				local numId = tonumber(emote.id)
				if numId and not _seenIds[numId] then
					_seenIds[numId] = true
					Emotes[#Emotes + 1] = {
						name          = tostring(emote.name),
						id            = numId,
						creatorName   = tostring(emote.creatorName      or ""),
						description   = tostring(emote.description      or ""),
						price         = emote.price,
						priceStatus   = tostring(emote.priceStatus      or ""),
						favoriteCount = emote.favoriteCount,
						createdUtc    = tostring(emote.itemCreatedUtc   or ""),
					}
				end
			end
		end
	end
	
	if #Emotes == 0 then
		Emotes = {
			{name = "Wave", id = 3576686446},
			{name = "Point", id = 3576823880},
			{name = "Dance", id = 3576720708},
			{name = "Laugh", id = 3576777185},
			{name = "Cheer", id = 3576738018}
		}
	end
	debugLog("LoadEmotes finished. Emotes count=" .. tostring(#Emotes))
end

AnimationPacks = {}
function LoadAnimations()
	local success, result = pcall(function()
		local response = loadModule("data/animations")
		return HttpService:JSONDecode(response)
	end)
	
	if success and result then
		local data = type(result) == "table" and (result.data or result)
		for _, pack in ipairs(data) do
			if pack.id and pack.name and pack.bundledItems then
				local function getAnimId(key)
					local arr = pack.bundledItems[key] or pack.bundledItems[tonumber(key)]
					if type(arr) == "table" and #arr > 0 then
						return tonumber(arr[1])
					elseif type(arr) == "number" then
						return arr
					end
					return nil
				end
				
				local climb = getAnimId("1")
				local fall = getAnimId("2")
				local walk = getAnimId("3")
				local swim = getAnimId("4")
				local idle = getAnimId("5")
				local run = getAnimId("6")
				local jump = getAnimId("7")
				
				if idle or walk then
					table.insert(AnimationPacks, {
						id = "anim_" .. tostring(pack.id),
						name = tostring(pack.name),
						isAnimationPack = true,
						Idle = idle,
						Walk = walk,
						Run = run,
						Jump = jump,
						Fall = fall,
						Climb = climb,
						Swim = swim
					})
				end
			end
		end
	end
	
	if #AnimationPacks == 0 then
		AnimationPacks = {
			{
				id = "anim_ninja",
				name = "Ninja Pack",
				isAnimationPack = true,
				Idle = 658832408,
				Walk = 658831143,
				Run = 658830056,
				Jump = 658832070,
				Fall = 658831500,
				Swim = 658832807,
				Climb = 658833139
			},
			{
				id = "anim_mage",
				name = "Mage Pack",
				isAnimationPack = true,
				Idle = 707742142,
				Walk = 707897309,
				Run = 707861613,
				Jump = 707853694,
				Fall = 707829716,
				Swim = 707876443,
				Climb = 707826056
			}
		}
	end
end

	return true
end

end
factories["player/combos"] = function()
-- Estado compartido mediante el contexto privado de la aplicacion.
return function(context)
	setfenv(1, context)

HUD, infoPanel, infoSpeedLbl, comboSlots, comboQueue_UI = nil, nil, nil, nil, nil
_currentInfoId, _currentInfoName = nil, nil
_comboLoopEnabled = false
_comboLoopList    = {}


-- ----------------------------------------------------------------
-- BÖLÜM 2 — ANİMASYON BLENDING & SEQUENCING (Combo Sistemi)
-- AnimationTrack:Play(0.3) ile 0.3s fade-in/out harmanlama,
-- Stopped sinyali ile otomatik sıralama, max 3 emote combo.
-- ----------------------------------------------------------------

ShowEmoteHUD, HideEmoteHUD = nil, nil

ComboQueue    = {}
isComboActive = false

function PlayComboStep(emoteId, emoteName)
	local animator = GetAnimator()
	if not animator then return end

	if currentAnimTrack and currentAnimTrack.IsPlaying then
		currentAnimTrack:Stop(0.3)
		task.wait(0.08)
	end

	local anim = _animCache[emoteId]
	if not anim then
		pcall(function()
			local ok, objects = pcall(function()
				return game:GetObjects("rbxassetid://" .. emoteId)
			end)
			if ok and objects and #objects > 0 then
				local item = objects[1]
				anim = item:IsA("Animation") and item
					or item:FindFirstChildWhichIsA("Animation", true)
			end
			if not anim then
				anim = Instance.new("Animation")
				anim.AnimationId = "rbxassetid://" .. emoteId
			end
			_animCache[emoteId] = anim
		end)
	end
	if not anim then return end

	pcall(function()
		local track = animator:LoadAnimation(anim)
		track.Priority = Enum.AnimationPriority.Action4
		track.Looped   = false

		track:Play(0.3)
		task.delay(0.05, function()
			if track.IsPlaying then
				track:AdjustSpeed(Settings.speed)
			end
		end)

		currentAnimTrack = track
		_genv().lastVexroEmote = {id = emoteId, name = emoteName}
		AddToRecent(emoteId)

		task.defer(function()
			if ShowEmoteHUD then ShowEmoteHUD(emoteId, emoteName) end
		end)

		track.Stopped:Connect(function()
			if not isComboActive then return end
			if #ComboQueue > 0 then
				local nxt = table.remove(ComboQueue, 1)
				PlayComboStep(nxt.id, nxt.name)
			else
				if _comboLoopEnabled and #_comboLoopList > 0 then
					ComboQueue = {}
					for i = 2, #_comboLoopList do
						ComboQueue[#ComboQueue + 1] = _comboLoopList[i]
					end
					PlayComboStep(_comboLoopList[1].id, _comboLoopList[1].name)
				else
					isComboActive = false
					task.defer(function()
						if HideEmoteHUD then HideEmoteHUD() end
					end)
					task.defer(function()
						if comboQueue_UI then comboQueue_UI = {} end
						if comboSlots then
							for j = 1, 3 do
								if comboSlots[j] then
									comboSlots[j].Text = L.slotLabel .. " " .. j
									TweenService:Create(comboSlots[j], TweenInfo.new(0.15), {
										BackgroundColor3 = Color3.fromRGB(30, 30, 46)
									}):Play()
								end
							end
						end
					end)
				end
			end
		end)
	end)
end

function StartCombo(emoteList)
	if #emoteList == 0 then return end
	isComboActive = true
	_comboLoopList = {}
	for _, e in ipairs(emoteList) do
		_comboLoopList[#_comboLoopList + 1] = {id = e.id, name = e.name}
	end
	ComboQueue = {}
	for i = 2, #emoteList do
		ComboQueue[#ComboQueue + 1] = emoteList[i]
	end
	PlayComboStep(emoteList[1].id, emoteList[1].name)
end

-- ----------------------------------------------------------------
-- BÖLÜM 3 — CANLI EMOTE HUD (Alt-Orta Şeffaf Panel)
-- RenderStepped canlı slider, hız butonları (0.1x–2x),
-- bilgi popup, sürüklenebilir knob, Disconnect ile FPS koruması.
-- ----------------------------------------------------------------

	return true
end

end
factories["player/copy_emote"] = function()
-- Estado compartido mediante el contexto privado de la aplicacion.
return function(context)
	setfenv(1, context)

PROMPT_TAG = "VexroCopyEmotePrompt"

function MakeCopyPrompt(targetChar)
	local root = targetChar:FindFirstChild("HumanoidRootPart")
	if not root then return end
	if root:FindFirstChild(PROMPT_TAG) then return end
	local prompt = Instance.new("ProximityPrompt")
	prompt.Name              = PROMPT_TAG
	prompt.ActionText        = L.copyEmote
	prompt.ObjectText        = ""
	prompt.MaxActivationDistance = 10
	prompt.HoldDuration      = 0
	prompt.RequiresLineOfSight = false
	prompt.Enabled           = true
	prompt.Parent            = root
	prompt.Triggered:Connect(function()
		local h = targetChar:FindFirstChildOfClass("Humanoid")
		if not h then return end
		local anim = h:FindFirstChildOfClass("Animator")
		if not anim then return end
		for _, track in ipairs(anim:GetPlayingAnimationTracks()) do
			local animId = tonumber(track.Animation.AnimationId:match("%d+"))
			if animId and EmotesById[animId] then
				PlayEmote(animId, EmotesById[animId].name)
				return
			end
		end
	end)
end

function RemoveCopyPrompt(targetChar)
	local root = targetChar:FindFirstChild("HumanoidRootPart")
	if root then
		local p = root:FindFirstChild(PROMPT_TAG)
		if p then p:Destroy() end
	end
end

_copyEmoteConns = {}

function EnableCopyEmotePrompts()
	for _, p in ipairs(Players:GetPlayers()) do
		if p ~= player and p.Character then
			MakeCopyPrompt(p.Character)
		end
	end
	_copyEmoteConns[#_copyEmoteConns + 1] = Players.PlayerAdded:Connect(function(p)
		_copyEmoteConns[#_copyEmoteConns + 1] = p.CharacterAdded:Connect(function(char)
			if Settings.copyEmoteEnabled then MakeCopyPrompt(char) end
		end)
	end)
	for _, p in ipairs(Players:GetPlayers()) do
		if p ~= player then
			_copyEmoteConns[#_copyEmoteConns + 1] = p.CharacterAdded:Connect(function(char)
				if Settings.copyEmoteEnabled then MakeCopyPrompt(char) end
			end)
		end
	end
end

function DisableCopyEmotePrompts()
	for _, conn in ipairs(_copyEmoteConns) do conn:Disconnect() end
	_copyEmoteConns = {}
	for _, p in ipairs(Players:GetPlayers()) do
		if p ~= player and p.Character then
			RemoveCopyPrompt(p.Character)
		end
	end
end

if Settings.copyEmoteEnabled then
	EnableCopyEmotePrompts()
end

copyEmoteBtn.MouseButton1Click:Connect(function()
	Settings.copyEmoteEnabled = not Settings.copyEmoteEnabled
	TweenService:Create(copyEmoteBtn, TweenInfo.new(0.2), {
		BackgroundColor3 = Settings.copyEmoteEnabled and currentTheme.success or currentTheme.critical
	}):Play()
	if Settings.copyEmoteEnabled then
		EnableCopyEmotePrompts()
	else
		DisableCopyEmotePrompts()
	end
	SaveData()
end)

-- ===============================================================
-- ===============================================================
-- ===============================================================

	return true
end

end
factories["player/emotes"] = function()
-- Estado compartido mediante el contexto privado de la aplicacion.
return function(context)
	setfenv(1, context)

currentAnimTrack = nil
lastEmoteTime = 0

function GetAnimator()
	local character = player.Character
	if not character then return nil end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return nil end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then
		animator = Instance.new("Animator")
		animator.Parent = humanoid
	end
	return animator
end

function StopAllTracks()
	local animator = GetAnimator()
	if animator then
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			pcall(function() 
				track:Stop(0.1)
			end)
		end
	end
	currentAnimTrack = nil
end

function ApplySpeedToAllTracks()
	local animator = GetAnimator()
	if animator then
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			pcall(function() track:AdjustSpeed(Settings.speed) end)
		end
	end
end


function StopEmote(showNotif)
	StopAllTracks()
	if showNotif then Notify(L.stopped, "", 113416463749658) end
	if FriendData.currentSyncPartner then
		pcall(function()
			SaveData()
		end)
		FriendData.currentSyncPartner = nil
	end
	if _genv().VexroBroadcastStop then
		pcall(_genv().VexroBroadcastStop)
	end
end

_heartbeatConn = RunService.Heartbeat:Connect(function()
	if Settings.stopOnWalk and currentAnimTrack and currentAnimTrack.IsPlaying then
		local character = player.Character
		if character then
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if humanoid and humanoid.MoveDirection.Magnitude > 0 then
				StopEmote(false)
			end
		end
		
		-- Instant sync partner walk & emote change detection
		if FriendData.currentSyncPartner then
			local partnerPlayer = Players:GetPlayerByUserId(tonumber(FriendData.currentSyncPartner))
			if partnerPlayer and partnerPlayer.Character then
				local partnerHumanoid = partnerPlayer.Character:FindFirstChildOfClass("Humanoid")
				if partnerHumanoid then
					if partnerHumanoid.MoveDirection.Magnitude > 0 then
						StopEmote(false)
					else
						local partnerAnimator = partnerHumanoid:FindFirstChildOfClass("Animator")
						if partnerAnimator then
							local tracks = partnerAnimator:GetPlayingAnimationTracks()
							for _, pt in ipairs(tracks) do
								if pt.Priority == Enum.AnimationPriority.Action4 and pt.IsPlaying and pt.Animation then
									local animIdStr = pt.Animation.AnimationId:match("%d+")
									if animIdStr then
										local animId = tonumber(animIdStr)
										if animId and _genv().lastVexroEmote and _genv().lastVexroEmote.id ~= animId then
											if EmotesById and EmotesById[animId] then
												local spd = Settings.speed > 0 and Settings.speed or 1
												local calcStartTime = workspace:GetServerTimeNow() - (pt.TimePosition / spd)
												PlayEmote(animId, EmotesById[animId].name, true, calcStartTime)
												break
											end
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end
end)

_animCache = {}

function PlayEmote(id, name, silent, syncStartTime)
	local animator = GetAnimator()
	if not animator then return end
	
	StopAllTracks()
	
	_genv().lastVexroEmote = {id = id, name = name}
	
	task.spawn(function()
		local anim = _animCache[id]
		
		if not anim then
			local successObj, objects = pcall(function()
				return game:GetObjects("rbxassetid://" .. id)
			end)
			
			if successObj and objects and #objects > 0 then
				local item = objects[1]
				if item:IsA("Animation") then
					anim = item
				else
					anim = item:FindFirstChildWhichIsA("Animation", true)
				end
			end
			
			if not anim then
				anim = Instance.new("Animation")
				anim.AnimationId = "rbxassetid://" .. id
			end
			
			_animCache[id] = anim
		end
		
		if _genv().lastVexroEmote and _genv().lastVexroEmote.id == id then
			local success, err = pcall(function()
				local track = animator:LoadAnimation(anim)
				track.Priority = Enum.AnimationPriority.Action4
				track.Looped = Settings.loopEmote
				track:Play(0.1)
				
				if syncStartTime then
					task.spawn(function()
						local waitTime = 0
						while track.Length <= 0 and waitTime < 3 do
							waitTime = waitTime + task.wait()
						end
						
						if track.Length > 0 then
							local tNow = workspace:GetServerTimeNow()
							local offset = tNow - tonumber(syncStartTime)
							if offset > 0 then
								pcall(function()
									track.TimePosition = (offset * Settings.speed) % track.Length
								end)
							end
						end
					end)
				end
				
				task.delay(0.05, function()
					track:AdjustSpeed(Settings.speed)
				end)
				
				currentAnimTrack = track
				AddToRecent(id)
			end)
			
			if success then
				if not silent then
					local speedTxt = Settings.speed ~= 1 and " (" .. Settings.speed .. "x)" or ""
					Notify(L.playing .. speedTxt, name, 129338178452237)
				end
				lastEmoteTime = tick()
				if _genv().VexroBroadcastSync and FriendData.syncEmote and not silent then
					pcall(_genv().VexroBroadcastSync, id, name, workspace:GetServerTimeNow())
				end
			else
				Notify(SafeUtf8Char(0x274C), L.emoteLoadFail)
			end
		end
	end)
end

-- ===============================================================
-- MAIN MENU
-- ===============================================================

	return true
end

end
factories["player/friend_follow"] = function()
-- Sigue solamente animaciones observables por este cliente.
return function(context)
    setfenv(1, context)
    local target, sourceTrack, sourceId, ownedTrack
    local pending, disposed = false, false
    local selectionVersion = 0
    local elapsed, missing, retryAt = 0, 0, 0
    local status = "Selecciona a un amigo del servidor."
    local connections = {}
    local basePlay, baseStop = PlayEmote, StopEmote
    local follow = {}
    LocalEmoteFollow = follow

    local function stopPlayback()
        if pending or (ownedTrack and currentAnimTrack == ownedTrack) then
            -- Cancelar tambien las cargas que aun no terminaron.
            _genv().lastVexroEmote = nil
            baseStop(false)
        end
        pending, ownedTrack, sourceTrack, sourceId = false, nil, nil, nil
    end
    function follow.Stop()
        selectionVersion += 1
        target = nil
        stopPlayback()
        status = "Seguimiento detenido."
    end
    function follow.GetTarget() return target end
    function follow.GetStatus() return status end
    function follow.Start(friend)
        if disposed or not friend or friend == player or friend.Parent ~= Players then return false end
        selectionVersion += 1
        local version = selectionVersion
        local ok, isFriend = pcall(function() return player:IsFriendsWith(friend.UserId) end)
        if version ~= selectionVersion then return false end
        if disposed or not ok or not isFriend or friend.Parent ~= Players then
            status = "No se pudo confirmar la amistad de Roblox."
            return false
        end
        follow.Stop()
        target = friend
        missing, retryAt = 0, 0
        status = "Esperando un emote visible de " .. friend.DisplayName .. "..."
        return true
    end

    local function visibleEmote(character)
        if not character then return nil end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator then return nil end
        local movement = {}
        local animate = character:FindFirstChild("Animate")
        if animate then
            for _, item in ipairs(animate:GetDescendants()) do
                if item:IsA("Animation") then
                    local id = item.AnimationId:match("%d+")
                    if id then movement[id] = true end
                end
            end
        end
        local best, bestId, priority = nil, nil, -1
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            local id = track.Animation and track.Animation.AnimationId:match("%d+")
            local value = track.Priority.Value
            if id and track.IsPlaying and not movement[id]
                and (EmotesById[tonumber(id)] or value >= Enum.AnimationPriority.Action.Value) then
                if value > priority or (value == priority and track == sourceTrack) then
                    best, bestId, priority = track, tonumber(id), value
                end
            end
        end
        return best, bestId
    end

    local function update(dt)
        if disposed or not target then return end
        if target.Parent ~= Players then follow.Stop(); status = "Tu amigo salio del servidor."; return end
        local track, id = visibleEmote(target.Character)
        if not track then
            missing += dt
            if missing >= 0.6 then stopPlayback() end
            status = "Esperando un emote visible de " .. target.DisplayName .. "..."
            return
        end
        missing = 0
        if track ~= sourceTrack or id ~= sourceId then
            stopPlayback()
            sourceTrack, sourceId = track, id
            retryAt = 0
        end
        if not ownedTrack and not pending and tick() >= retryAt then
            -- No confundir una pista manual anterior con el nuevo emote pendiente.
            baseStop(false)
            pending = true
            retryAt = tick() + 3
            local meta = EmotesById[id]
            local ok = pcall(basePlay, id, meta and meta.name or ("Emote " .. id), true)
            if not ok then pending = false end
        end
        if pending then
            local active = _genv().lastVexroEmote
            if currentAnimTrack and currentAnimTrack.IsPlaying and active and active.id == id then
                ownedTrack, pending = currentAnimTrack, false
            elseif tick() >= retryAt then
                _genv().lastVexroEmote = nil
                pending = false
                status = "No se pudo cargar el emote; reintentando..."
                return
            end
        end
        if ownedTrack and currentAnimTrack == ownedTrack then
            if not ownedTrack.IsPlaying then ownedTrack = nil; return end
            ownedTrack.Looped = track.Looped
            ownedTrack:AdjustSpeed(track.Speed)
            if ownedTrack.Length > 0 then
                local position = track.TimePosition
                if track.Looped then position %= ownedTrack.Length else position = math.min(position, ownedTrack.Length) end
                if math.abs(ownedTrack.TimePosition - position) > 0.15 then ownedTrack.TimePosition = position end
            end
            status = "Siguiendo a " .. target.DisplayName .. " (experimental)"
        end
    end

    -- La reproduccion manual siempre tiene prioridad.
    PlayEmote = function(...) follow.Stop(); return basePlay(...) end
    StopEmote = function(...) follow.Stop(); return baseStop(...) end
    local basePack, baseCombo = EquipAnimationPack, StartCombo
    EquipAnimationPack = function(...) follow.Stop(); return basePack(...) end
    StartCombo = function(...) follow.Stop(); return baseCombo(...) end
    connections[#connections + 1] = RunService.Heartbeat:Connect(function(dt)
        elapsed += dt
        if elapsed < 0.15 then return end
        local step = elapsed; elapsed = 0
        local ok = pcall(update, step)
        if not ok then status = "No se pudo leer la animacion de tu amigo." end
    end)
    connections[#connections + 1] = player.CharacterRemoving:Connect(function() follow.Stop() end)
    connections[#connections + 1] = Players.PlayerRemoving:Connect(function(leaving)
        if leaving == target then follow.Stop(); status = "Tu amigo salio del servidor." end
    end)
    function follow.Destroy()
        if disposed then return end
        disposed = true
        follow.Stop()
        for _, connection in ipairs(connections) do connection:Disconnect() end
    end
    connections[#connections + 1] = gui.Destroying:Connect(follow.Destroy)
    return true
end

end
factories["player/hud_integration"] = function()
-- Estado compartido mediante el contexto privado de la aplicacion.
return function(context)
	setfenv(1, context)

_origPlayEmote = PlayEmote
PlayEmote = function(id, name, silent, syncStartTime)
	if tostring(id):find("anim_") then
		for _, pack in ipairs(AnimationPacks) do
			if pack.id == id then
				EquipAnimationPack(pack)
				break
			end
		end
		return
	end
	_origPlayEmote(id, name, silent, syncStartTime)
	local myToken = _hudHideToken + 1
	_hudHideToken = myToken
	task.defer(function()
		if _hudHideToken ~= myToken then return end
		if currentAnimTrack then
			ShowEmoteHUD(id, name)
			local tracked = currentAnimTrack
			tracked.Stopped:Connect(function()
				if (currentAnimTrack == tracked or not currentAnimTrack)
				and not isComboActive then
					HideEmoteHUD()
				end
			end)
		end
	end)
end

_origStopEmote = StopEmote
StopEmote = function(showNotif)
	_origStopEmote(showNotif)
	isComboActive = false
	ComboQueue    = {}
	HideEmoteHUD()
end

-- ----------------------------------------------------------------
-- BOLUM 5 - COMBO SIRASI
-- ----------------------------------------------------------------

	return true
end

end
